<?php
declare(strict_types=1);
require_once __DIR__ . '/../../lib/mdm_helpers.php';
$u=require_role(['admin','principal','clerk']);$sid=(int)$u['school_id'];$pdo=db();$month=(int)($_GET['month']??$_POST['month']??date('m'));$year=(int)($_GET['year']??$_POST['year']??date('Y'));
if($_SERVER['REQUEST_METHOD']==='POST'&&valid_csrf($_POST['csrf']??null)){ $p=$pdo->prepare('REPLACE INTO mdm_daily(school_id,date,class_group,menu_id,beneficiaries,cooked,holiday,remarks,locked) VALUES(?,?,?,?,?,?,?,?,COALESCE((SELECT locked FROM mdm_daily WHERE school_id=? AND date=? AND class_group=?),0))');foreach((array)($_POST['date']??[]) as $i=>$date)foreach(['1-5','6-8'] as $g)$p->execute([$sid,$date,$g,(int)($_POST['menu'][$g][$i]??0)?:null,(int)($_POST['beneficiaries'][$g][$i]??0),isset($_POST['cooked'][$g][$i])?1:0,0,trim((string)($_POST['remarks'][$g][$i]??'')),$sid,$date,$g]);flash_set('success','मासिक नोंदी जतन झाल्या.');}
$menus=$pdo->prepare('SELECT * FROM mdm_menus WHERE school_id=? AND active=1 ORDER BY weekday');$menus->execute([$sid]);$menus=$menus->fetchAll();$days=cal_days_in_month(CAL_GREGORIAN,$month,$year);mdm_layout_start('मासिक जलद नोंद — पोषण आहार');
?>
<form method="post" class="bg-white border rounded-2xl p-6 overflow-auto"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="flex gap-3 mb-5"><input type="number" name="month" value="<?=$month?>" min="1" max="12"><input type="number" name="year" value="<?=$year?>"></div><table class="w-full text-xs"><thead><tr><th>दिनांक</th><th>१–५ लाभार्थी</th><th>१–५ मेनू</th><th>६–८ लाभार्थी</th><th>६–८ मेनू</th></tr></thead><tbody><?php for($d=1;$d<=$days;$d++):$date=sprintf('%04d-%02d-%02d',$year,$month,$d);?><tr><td><input type="hidden" name="date[]" value="<?=$date?>"><?=$date?></td><?php foreach(['1-5','6-8'] as $g):?><td><input type="number" name="beneficiaries[<?=$g?>][]" value="0" class="w-24"></td><td><select name="menu[<?=$g?>][]"><option value="0">—</option><?php foreach($menus as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select></td><?php endforeach;?></tr><?php endfor;?></tbody></table><button class="mt-5 bg-gold rounded-xl px-5 py-3">जतन करा</button></form>
<?php layout_end(); ?>
